//! Golden-vector parity: the Rust journey queries answer exactly what
//! multistate's reference implementation answers.
//!
//! `tests/fixtures/journey-golden.json` is generated by
//! `tests/fixtures/journey/generate_golden.py`, which runs multistate's
//! `graph_utils.py` (`get_reachable_states`, `compute_shortest_distances`,
//! `find_terminal_states`) over fixture graphs; the sidecar
//! `journey-golden.provenance.json` names the multistate commit and the
//! fixture's sha256. Plan
//! `2026-09-20-ui-bridge-represents-the-users-path-and-the-passage-of-time`,
//! D2 / Phase 2 acceptance 1. Never hand-edit the fixture: regenerate it.
//!
//! Every fixture edge is written to the ledger as one
//! [`JourneyEdgeObservation`] row — the multistate-checked `affordanceEdges`
//! as `affordance`/`changed`, the journey-only `otherEdges` with their own
//! trigger and outcome — and the graph is built with no frontier, so every
//! negative is settled and the comparison is exact.

use std::collections::BTreeMap;
use std::path::PathBuf;

use qontinui_types::journey::{
    build_graph, dead_ends, reachable_from, requires_prior_knowledge, steps_to, ChokePoint,
    EdgeOutcome, JourneyEdgeObservation, JourneyFilter, JourneyGraph, JourneyLedgerHealth,
    JourneyNode, JourneyTrigger, LedgerState, NavigationTriggerKind, RunKind,
};
use serde_json::Value;
use sha2::{Digest, Sha256};

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn load() -> Value {
    let bytes = std::fs::read(fixtures().join("journey-golden.json")).expect("golden fixture");
    let provenance: Value = serde_json::from_slice(
        &std::fs::read(fixtures().join("journey-golden.provenance.json")).expect("sidecar"),
    )
    .expect("sidecar is JSON");
    let digest = hex::encode(Sha256::digest(&bytes));
    assert_eq!(
        provenance["sha256"].as_str(),
        Some(digest.as_str()),
        "journey-golden.json does not match its provenance sha256 — regenerate it with \
         generate_golden.py instead of editing it"
    );
    let commit = provenance["multistate_commit"].as_str().unwrap_or("");
    assert!(
        commit.len() == 40 && commit.bytes().all(|b| b.is_ascii_hexdigit()),
        "provenance must name the multistate commit: {commit:?}"
    );
    serde_json::from_slice(&bytes).expect("golden is JSON")
}

struct Family<'a> {
    name: &'a str,
    spec: &'a str,
    raw: &'a Value,
}

impl Family<'_> {
    fn key(&self, name: &str) -> String {
        self.node(name).key()
    }

    fn node(&self, name: &str) -> JourneyNode {
        JourneyNode::new(Some(self.spec.into()), [name.to_string()], None, None)
    }

    fn name_of(&self, key: &str) -> String {
        key.strip_prefix(&format!("{}#", self.spec))
            .unwrap_or_else(|| panic!("{}: foreign key {key}", self.name))
            .to_string()
    }

    fn nodes(&self) -> Vec<String> {
        self.raw["nodes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect()
    }

    fn row(
        &self,
        i: usize,
        from: &str,
        to: &str,
        kind: &str,
        outcome: &str,
    ) -> JourneyEdgeObservation {
        let kind: NavigationTriggerKind = serde_json::from_value(Value::from(kind)).unwrap();
        let outcome: EdgeOutcome = serde_json::from_value(Value::from(outcome)).unwrap();
        let trigger = if kind == NavigationTriggerKind::Affordance {
            JourneyTrigger {
                action_type: "click".into(),
                target_fingerprint: Some(format!("{from}->{to}")),
                target_role: Some("link".into()),
                declared_effect: None,
                navigation_trigger: kind,
                choke_point: ChokePoint::ElementAction,
            }
        } else {
            JourneyTrigger {
                action_type: "navigate".into(),
                target_fingerprint: None,
                target_role: None,
                declared_effect: None,
                navigation_trigger: kind,
                choke_point: ChokePoint::Navigation,
            }
        };
        JourneyEdgeObservation {
            id: format!("{}-{i}", self.name),
            observed_at: "2026-10-01T00:00:00Z".into(),
            app_id: "golden".into(),
            app_version: None,
            runner_build_id: "golden".into(),
            runner_instance: "golden".into(),
            run_id: None,
            run_kind: RunKind::Explorer,
            from_node: self.node(from),
            to_node: Some(self.node(to)),
            trigger,
            outcome,
            invalidated_at: None,
            invalidated_reason: None,
            invalidated_by: None,
            invalidation_token: None,
        }
    }

    fn graph(&self) -> JourneyGraph {
        let mut rows = Vec::new();
        for pair in self.raw["affordanceEdges"].as_array().unwrap() {
            let (f, t) = (pair[0].as_str().unwrap(), pair[1].as_str().unwrap());
            rows.push(self.row(rows.len(), f, t, "affordance", "changed"));
        }
        for e in self.raw["otherEdges"].as_array().unwrap() {
            rows.push(self.row(
                rows.len(),
                e["from"].as_str().unwrap(),
                e["to"].as_str().unwrap(),
                e["trigger"].as_str().unwrap(),
                e["outcome"].as_str().unwrap(),
            ));
        }
        let ledger = JourneyLedgerHealth {
            state: LedgerState::Writing,
            detail: "golden fixture".into(),
        };
        let g = build_graph(&rows, &[], &ledger, &JourneyFilter::default());
        assert!(
            g.rejected.is_empty(),
            "{}: rejected {:?}",
            self.name,
            g.rejected
        );
        // Every fixture node is observed, and nothing else is.
        let mut observed: Vec<String> = g.nodes.iter().map(|n| self.name_of(&n.key)).collect();
        observed.sort();
        let mut declared = self.nodes();
        declared.sort();
        assert_eq!(observed, declared, "{}: observed node set", self.name);
        g
    }
}

fn families(golden: &Value) -> Vec<Family<'_>> {
    let spec = golden["nodeSpecId"].as_str().expect("nodeSpecId");
    golden["families"]
        .as_array()
        .expect("families")
        .iter()
        .map(|raw| Family {
            name: raw["name"].as_str().unwrap(),
            spec,
            raw,
        })
        .collect()
}

#[test]
fn rust_answers_equal_multistate_on_every_fixture() {
    let golden = load();
    let checked: Vec<_> = families(&golden)
        .into_iter()
        .filter(|f| f.raw["source"] == "multistate")
        .collect();
    assert!(
        checked.len() >= 4,
        "the golden must carry at least four multistate-checked families"
    );
    for family in checked {
        let g = family.graph();
        let expected = &family.raw["multistate"];

        for start in family.nodes() {
            let r = reachable_from(&g, &family.key(&start));
            assert!(r.from_observed);
            assert!(r.frontier.is_settled(&r.coverage, true));

            // get_reachable_states
            let got: Vec<String> = r
                .reachable
                .iter()
                .map(|n| family.name_of(&n.node_key))
                .collect();
            let want: Vec<String> =
                serde_json::from_value(expected["reachable"][&start].clone()).unwrap();
            let mut got_sorted = got.clone();
            got_sorted.sort();
            assert_eq!(got_sorted, want, "{}: reachable_from({start})", family.name);

            // compute_shortest_distances
            let got: BTreeMap<String, u64> = r
                .reachable
                .iter()
                .map(|n| (family.name_of(&n.node_key), n.steps))
                .collect();
            let want: BTreeMap<String, u64> =
                serde_json::from_value(expected["distances"][&start].clone()).unwrap();
            assert_eq!(got, want, "{}: distances from {start}", family.name);

            // steps_to agrees with the distances for every pair, and its path
            // is a real path of that length over navigation edges.
            for target in family.nodes() {
                let s = steps_to(&g, &family.key(&start), &family.key(&target));
                assert_eq!(
                    s.steps,
                    want.get(&target).copied(),
                    "{}: steps_to({start}, {target})",
                    family.name
                );
                assert_eq!(s.path.len() as u64, s.steps.unwrap_or(0));
                let mut at = family.key(&start);
                for edge in &s.path {
                    assert_eq!(edge.from_key, at);
                    assert_eq!(
                        edge.trigger.navigation_trigger,
                        NavigationTriggerKind::Affordance
                    );
                    assert_eq!(edge.outcome, EdgeOutcome::Changed);
                    at = edge.to_key.clone();
                }
                if s.steps.is_some() {
                    assert_eq!(at, family.key(&target));
                }
            }
        }

        // find_terminal_states (over the self-loop-free projection)
        let d = dead_ends(&g);
        assert!(d.unexplored.is_empty());
        let got: Vec<String> = d
            .dead_ends
            .iter()
            .map(|n| family.name_of(&n.node_key))
            .collect();
        let want: Vec<String> =
            serde_json::from_value(expected["terminalStatesWithoutSelfLoops"].clone()).unwrap();
        assert_eq!(got, want, "{}: dead_ends", family.name);

        // backOnly (hand-verified)
        let got: Vec<String> = d
            .dead_ends
            .iter()
            .filter(|n| n.back_only == Some(true))
            .map(|n| family.name_of(&n.node_key))
            .collect();
        let want: Vec<String> =
            serde_json::from_value(family.raw["handVerified"]["backOnly"].clone()).unwrap();
        assert_eq!(got, want, "{}: back_only", family.name);
    }
}

#[test]
fn requires_prior_knowledge_matches_the_hand_verified_family() {
    let golden = load();
    let family = families(&golden)
        .into_iter()
        .find(|f| f.name == "prior_knowledge")
        .expect("the hand-verified prior_knowledge family");
    assert_eq!(family.raw["source"], "hand-verified");
    let g = family.graph();
    let p = requires_prior_knowledge(&g);
    // The hand-verified vector is the QUALIFY rule (which nodes are reached
    // only by URL). Whether each qualifying node is then SETTLED is a
    // separate layer: the family carries an errored click to another node,
    // whose real destination is unknown, so every candidate is `unsettled`
    // with that cause. Compare the qualifying set across both lists.
    let got: BTreeMap<String, BTreeMap<String, u64>> = p
        .nodes
        .iter()
        .map(|n| (family.name_of(&n.node_key), n.arrivals.clone()))
        .chain(
            p.unsettled
                .iter()
                .map(|n| (family.name_of(&n.node_key), n.arrivals.clone())),
        )
        .collect();
    let want: BTreeMap<String, BTreeMap<String, u64>> =
        serde_json::from_value(family.raw["handVerified"]["requiresPriorKnowledge"].clone())
            .unwrap();
    assert_eq!(got, want);
    assert!(
        g.unknown_destination_arrivals > 0,
        "the family's errored click"
    );
    assert!(p.nodes.is_empty());
    assert!(p
        .unsettled
        .iter()
        .all(|n| n.unknown_destination_arrivals == g.unknown_destination_arrivals));
    // No frontier is given; the only unexplored departures are the family's
    // own error / settle_timeout edges to another node.
    assert_eq!(p.frontier.open_entries, 0);
    assert!(
        p.frontier
            .unmeasured(&p.coverage, true)
            .iter()
            .all(|(d, _, _)| matches!(*d, "errored_departures" | "settle_timeout_departures")),
        "{:?}",
        p.frontier.unmeasured(&p.coverage, true)
    );
}
